const RadioButton = ({ label, value, checked, onChange }) => {
  return (
    <label className={`radio-option ${checked ? 'selected' : ''}`}>
      <input
        type="radio"
        name="notification-preference"
        value={value}
        checked={checked}
        onChange={() => onChange(value)}
      />
      <span className="label-text">{label}</span>
    </label>
  );
};

const NotificationForm = () => {
  const [preference, setPreference] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!preference) {
      alert('Please select a notification preference.');
      return;
    }
    alert(`Preferences saved: ${preference}`);
  };

  const options = [
    { label: 'Email', value: 'email' },
    { label: 'SMS', value: 'sms' },
    { label: 'Push Notifications', value: 'push' },
  ];

  return (
    <div className="form-container">
      <h1>Preferences</h1>
      <form onSubmit={handleSubmit}>
        <div className="form-field">
          <fieldset>
            <legend>How do you prefer to receive notifications?</legend>
            <div className="radio-group">
              {options.map((option) => (
                <RadioButton
                  key={option.value}
                  label={option.label}
                  value={option.value}
                  checked={preference === option.value}
                  onChange={setPreference}
                />
              ))}
            </div>
          </fieldset>
        </div>
        <button type="submit" className="submit-button">
          Save Preferences
        </button>
      </form>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<NotificationForm />);
